package cn.codedog.service;
import java.util.*;import java.time.Instant;import java.sql.Timestamp;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;
@Service public class RankingRewardRuleService {
 private final JdbcTemplate j;public RankingRewardRuleService(JdbcTemplate j){this.j=j;}
 public record Rule(int lowStockThreshold,int perStudentLimit,Instant startsAt,Instant endsAt,String instructions){}
 public List<Map<String,Object>> rules(String owner,boolean student){return j.queryForList("SELECT r.id reward_id,r.reward_name,r.stock,COALESCE(q.low_stock_threshold,3) low_stock_threshold,COALESCE(q.per_student_limit,0) per_student_limit,q.starts_at,q.ends_at,COALESCE(q.instructions,'') instructions FROM ranking_rewards r LEFT JOIN ranking_reward_rules q ON q.reward_id=r.id WHERE r.owner_username=? AND r.deleted_at IS NULL"+(student?" AND r.enabled=TRUE":"")+" ORDER BY r.id",owner);}
 @Transactional public Map<String,Object> save(String owner,long reward,Rule b){if(b.lowStockThreshold()<0||b.perStudentLimit()<0||b.instructions()==null||b.instructions().length()>500||b.startsAt()!=null&&b.endsAt()!=null&&!b.endsAt().isAfter(b.startsAt()))throw RankingPointsService.conflict("库存阈值、限兑次数或兑换时间范围不合法");j.queryForList("SELECT username FROM users WHERE username=? FOR UPDATE",owner);var found=j.queryForList("SELECT id FROM ranking_rewards WHERE id=? AND owner_username=? AND deleted_at IS NULL FOR UPDATE",reward,owner);if(found.isEmpty())throw RankingPointsService.conflict("奖品不存在");var before=j.queryForList("SELECT * FROM ranking_reward_rules WHERE reward_id=? AND owner_username=?",reward,owner);
 j.update("INSERT INTO ranking_reward_rules(reward_id,owner_username,low_stock_threshold,per_student_limit,starts_at,ends_at,instructions) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE low_stock_threshold=VALUES(low_stock_threshold),per_student_limit=VALUES(per_student_limit),starts_at=VALUES(starts_at),ends_at=VALUES(ends_at),instructions=VALUES(instructions),updated_at=CURRENT_TIMESTAMP(6)",reward,owner,b.lowStockThreshold(),b.perStudentLimit(),b.startsAt()==null?null:Timestamp.from(b.startsAt()),b.endsAt()==null?null:Timestamp.from(b.endsAt()),b.instructions());return Map.of("before",before,"after",b);}
 public void enforce(String owner,String student,long reward){var rows=j.queryForList("SELECT * FROM ranking_reward_rules WHERE reward_id=? AND owner_username=?",reward,owner);if(rows.isEmpty())return;var r=rows.getFirst();Instant now=Instant.now();if(r.get("starts_at")!=null&&now.isBefore(((Timestamp)r.get("starts_at")).toInstant()))throw RankingPointsService.conflict("该奖品尚未开始兑换");if(r.get("ends_at")!=null&&!now.isBefore(((Timestamp)r.get("ends_at")).toInstant()))throw RankingPointsService.conflict("该奖品兑换已结束");int limit=((Number)r.get("per_student_limit")).intValue();if(limit>0&&j.queryForObject("SELECT COUNT(*) FROM ranking_reward_redemptions WHERE owner_username=? AND student_id=? AND reward_id=? AND status<>'CANCELLED'",Integer.class,owner,student,reward)>=limit)throw RankingPointsService.conflict("已达到该奖品每人累计限兑次数");}
 public void lowStock(String owner,long reward,String key){var rows=j.queryForList("SELECT r.reward_name,r.stock,COALESCE(q.low_stock_threshold,3) threshold FROM ranking_rewards r LEFT JOIN ranking_reward_rules q ON q.reward_id=r.id WHERE r.id=? AND r.owner_username=?",reward,owner);if(rows.isEmpty())return;var r=rows.getFirst();if(((Number)r.get("stock")).intValue()<=((Number)r.get("threshold")).intValue())new RankingMessageService(j).teacher(owner,"stock:"+key,"奖品库存预警",r.get("reward_name")+" 剩余 "+r.get("stock")+" 件","rewards");}
}
